  1	import { chmodSync } from 'node:fs';
  2	import { getConfigPath } from '../utils/paths.js';
  3	import { readJsonFile, writeJsonFile, FileNotFoundError } from '../storage/json-storage.js';
  4	import type { AppConfig, GitCredentialEntry } from './config.types.js';
  5	import { toKebabCase } from '../utils/slug.js';
  6	import {
  7	    DEFAULT_NOTES_CARD_HEIGHT,
  8	    DEFAULT_NOTES_COLUMNS,
  9	    MIN_NOTES_CARD_HEIGHT,
 10	    MAX_NOTES_CARD_HEIGHT,
 11	    MIN_NOTES_COLUMNS,
 12	    MAX_NOTES_COLUMNS,
 13	    MIN_POLLING_INTERVAL_SECONDS,
 14	    MAX_POLLING_INTERVAL_SECONDS,
 15	    MIN_CLONE_DEPTH,
 16	    MAX_CLONE_DEPTH,
 17	    MIN_SERVER_PORT,
 18	    MAX_SERVER_PORT,
 19	} from './config.constants.js';
 20	
 21	const REQUIRED_FIELDS: ReadonlyArray<keyof AppConfig> = ['projectsFolder', 'storageFolder'];
 22	
 23	// When adding a new non-optional AppConfig field with a sensible default: add the
 24	// key to the Pick<AppConfig, ...> union and its value here, then update loadConfig()
 25	// to fall back to it. The satisfies guard below will catch if DEFAULTS is incomplete.
 26	export const DEFAULTS: Readonly<Pick<AppConfig, 'cloneDepth' | 'serverPort' | 'gitPollingIntervalSeconds' | 'notesCardHeight' | 'notesColumns'>> = {
 27	    cloneDepth: 50,
 28	    serverPort: 4200,
 29	    gitPollingIntervalSeconds: 30,
 30	    notesCardHeight: DEFAULT_NOTES_CARD_HEIGHT,
 31	    notesColumns: DEFAULT_NOTES_COLUMNS,
 32	};
 33	
 34	// Compile-time guard: ensures DEFAULTS + required fields cover the full AppConfig shape.
 35	// If a new required field is added to AppConfig without updating DEFAULTS, this line
 36	// will produce a type error.
 37	const _defaultsCoverageGuard: AppConfig = {
 38	    ...DEFAULTS,
 39	    projectsFolder: '',
 40	    storageFolder: '',
 41	} satisfies AppConfig;
 42	void _defaultsCoverageGuard;
 43	
 44	/**
 45	 * Loads, validates, and returns the application configuration from `config.json`.
 46	 *
 47	 * **Setup:** Copy `config.dist.json` to `config.json` and fill in the required
 48	 * fields before running the tool.
 49	 *
 50	 * @param configPath Optional absolute path to the config file. Defaults to the
 51	 *   `config.json` in the tool root. Pass a custom path in tests to avoid touching
 52	 *   the real config file.
 53	 * @throws {Error} If `config.json` does not exist (with instruction to copy from
 54	 *   `config.dist.json`).
 55	 * @throws {Error} If any required field is missing, non-string, or empty.
 56	 */
 57	export function loadConfig(configPath?: string): AppConfig {
 58	    const resolvedConfigPath = configPath ?? getConfigPath();
 59	    let raw: Record<string, unknown>;
 60	
 61	    try {
 62	        raw = readJsonFile<Record<string, unknown>>(resolvedConfigPath);
 63	    } catch (err) {
 64	        if (err instanceof FileNotFoundError) {
 65	            throw new Error(
 66	                `config.json not found at "${resolvedConfigPath}". ` +
 67	                `Copy config.dist.json to config.json and fill in the required fields.`
 68	            );
 69	        }
 70	        throw err;
 71	    }
 72	
 73	    for (const field of REQUIRED_FIELDS) {
 74	        const value = raw[field];
 75	        if (typeof value !== 'string' || value.trim() === '') {
 76	            throw new Error(
 77	                `Configuration error: required field "${field}" must be a non-empty string in config.json.`
 78	            );
 79	        }
 80	    }
 81	
 82	    return {
 83	        projectsFolder: raw['projectsFolder'] as string,
 84	        storageFolder: raw['storageFolder'] as string,
 85	        cloneDepth: parseIntegerField(raw['cloneDepth'], 'cloneDepth', DEFAULTS.cloneDepth, MIN_CLONE_DEPTH, MAX_CLONE_DEPTH),
 86	        serverPort: parseIntegerField(raw['serverPort'], 'serverPort', DEFAULTS.serverPort, MIN_SERVER_PORT, MAX_SERVER_PORT),
 87	        gitPollingIntervalSeconds: parseIntegerField(
 88	            raw['gitPollingIntervalSeconds'],
 89	            'gitPollingIntervalSeconds',
 90	            DEFAULTS.gitPollingIntervalSeconds,
 91	            MIN_POLLING_INTERVAL_SECONDS,
 92	            MAX_POLLING_INTERVAL_SECONDS,
 93	        ),
 94	        gitCredentials: parseGitCredentials(raw['gitCredentials']),
 95	        webserverUrl: typeof raw['webserverUrl'] === 'string' && raw['webserverUrl'].trim() !== ''
 96	            ? raw['webserverUrl'].trim().replace(/\/+$/, '')
 97	            : undefined,
 98	        notesCardHeight: parseIntegerField(
 99	            raw['notesCardHeight'],
100	            'notesCardHeight',

101	            DEFAULTS.notesCardHeight,
102	            MIN_NOTES_CARD_HEIGHT,
103	            MAX_NOTES_CARD_HEIGHT,
104	        ),
105	        notesColumns: parseIntegerField(
106	            raw['notesColumns'],
107	            'notesColumns',
108	            DEFAULTS.notesColumns,
109	            MIN_NOTES_COLUMNS,
110	            MAX_NOTES_COLUMNS,
111	        ),
112	    };
113	}
114	
115	/**
116	 * Parses a numeric config field, enforcing integer-only values and optional
117	 * `[min, max]` range bounds.
118	 *
119	 * - If `value` is not a `number`, returns `defaultValue`.
120	 * - If `value` is a number but not an integer (e.g. a float like `220.5`),
121	 *   returns `defaultValue`.
122	 * - If `min` and `max` are provided and the integer value is outside that range,
123	 *   emits `console.warn` but returns the value as-is (no clamping).
124	 *
125	 * @param value     Raw value read from the config file.
126	 * @param fieldName Field name used in warning messages.
127	 * @param defaultValue Fallback value for non-numeric or float inputs.
128	 * @param min       Optional lower bound (inclusive).
129	 * @param max       Optional upper bound (inclusive).
130	 */
131	function parseIntegerField(
132	    value: unknown,
133	    fieldName: string,
134	    defaultValue: number,
135	    min?: number,
136	    max?: number,
137	): number {
138	    if (typeof value !== 'number') {
139	        return defaultValue;
140	    }
141	    if (!Number.isInteger(value)) {
142	        return defaultValue;
143	    }
144	    if (min !== undefined && max !== undefined && (value < min || value > max)) {
145	        console.warn(
146	            `Configuration warning: "${fieldName}" value ${value} is outside the allowed range ` +
147	            `[${min}, ${max}]. The value will be used as-is.`
148	        );
149	    }
150	    return value;
151	}
152	
153	/**
154	 * Validates and returns the `gitCredentials` value from the raw config,
155	 * auto-migrating the legacy `Record<string, string>` format to the new
156	 * `GitCredentialEntry[]` format when necessary.
157	 *
158	 * **Accepted inputs:**
159	 * - `undefined` / `null` → returns `undefined`
160	 * - `GitCredentialEntry[]` (new format) → validated and returned as-is
161	 * - `Record<string, string>` (old format, hostname→token map) → migrated to
162	 *   `GitCredentialEntry[]` with `id` derived from the hostname in kebab-case
163	 *   and `label` set to the hostname. Colliding IDs get a numeric suffix (`-2`,
164	 *   `-3`, …).
165	 * - An empty array `[]` → returns `[]`
166	 *
167	 * **Validation (new-format arrays):**
168	 * - Every entry must have non-empty `id`, `label`, `host`, and `token` fields.
169	 * - Duplicate `id` values within the array are rejected.
170	 *
171	 * @returns `undefined` when the field is absent or null; otherwise a
172	 *   `GitCredentialEntry[]` (possibly empty).
173	 * @throws {Error} If the value is present but structurally invalid, or if any
174	 *   entry fails validation.
175	 */
176	function parseGitCredentials(value: unknown): GitCredentialEntry[] | undefined {
177	    if (value === undefined || value === null) {
178	        return undefined;
179	    }
180	
181	    // --- New format: array of GitCredentialEntry objects ---
182	    if (Array.isArray(value)) {
183	        // Empty array is valid — treat as "no credentials".
184	        if (value.length === 0) {
185	            return [];
186	        }
187	
188	        const seenIds = new Set<string>();
189	
190	        for (let i = 0; i < value.length; i++) {
191	            const entry = value[i] as Record<string, unknown>;
192	
193	            if (typeof entry !== 'object' || entry === null || Array.isArray(entry)) {
194	                throw new Error(
195	                    `Configuration error: gitCredentials[${i}] must be a credential object, got ${typeof entry}.`
196	                );
197	            }
198	
199	            for (const field of ['id', 'label', 'host', 'token'] as const) {
200	                const fieldValue = entry[field];
201	                if (typeof fieldValue !== 'string' || fieldValue.trim() === '') {
202	                    throw new Error(
203	                        `Configuration error: gitCredentials[${i}].${field} must be a non-empty string.`
204	                    );
205	                }
206	            }
207	
208	            const id = (entry['id'] as string).trim();
209	            if (seenIds.has(id)) {
210	                throw new Error(
